// Solution for: Home Appliance Energy Report
import java.util.*; public class W92_q5 {public static void main(String[]z){Scanner s=new Scanner(System.in);int n=s.nextInt();double total=0;for(int i=0;i<n;i++){String t=s.next().toUpperCase();double h=s.nextDouble();boolean saver=s.hasNext("SAVER");if(saver)s.next();double power=t.equals("FRIDGE")?150:t.equals("AC")?1500:t.equals("TV")?100:500;if(saver&&!t.equals("AC")&&!t.equals("WASHER")){System.out.println(t+": saver mode not supported");continue;}double units=power*h/1000.0;if(saver)units*=.75;double cost=units*8;System.out.printf("%s: Units=%.2f Cost=%.2f%n",t,units,cost);total+=cost;}System.out.printf("Total Cost: %.2f%n",total);}}
